INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘承训", "aliases": ["劉承訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的儿子。947年九月刘知远诏赴澶、魏劳军时，任命他为东京留守。生卒年尚未录入。", "biography": null, "status": "draft", "id": "4e08b6fa-2adc-5da7-b83b-0448f2cda108"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "李仁达", "aliases": ["李仁達", "李弘义", "李弘義", "李弘达", "李弘達", "李宏达", "李宏達", "李达", "李達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光州人，曾任闽元从指挥使，多次在建州、福州之间投奔不同执政者。945年与陈继珣、黄仁讽发动福州政变，杀王继昌和吴成义，拥立僧卓岩明。后来又杀黄仁讽、陈继珣，将福州兵权集中到自己手中。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "97ca7dea-54b1-5a38-a747-3dc803037d55"}, {"name": "鲍修让", "aliases": ["鮑修讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越东南安抚使。947年钱弘佐派他率军驻守福州。生卒年未载。", "biography": null, "status": "draft", "id": "10a9b07f-dbdb-57a9-b923-561e2cfa6d86"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "吴崇恽", "aliases": ["吳崇惲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年以雄武都押牙身份带王处回书信招侯益归蜀。《宋史》侯益传记他为侯益旧属、秦州押衙，后任绵州刺史，受孟昶派遣厚赠侯益；职名按出处分别保留。生卒年未载。", "biography": null, "status": "draft", "id": "101778ed-1ba3-58c1-b7d5-0a116caec712"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "吴程", "aliases": ["吳程"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "山阴人，吴越丞相。947年十二月鲍修让将李仁达首级送到钱塘后，钱弘倧任吴程主持威武节度事务。生卒年未载。", "biography": null, "status": "draft", "id": "70950e94-6804-5b3e-afb7-43c0ab271dea"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "胡进思", "aliases": ["胡進思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖州人，吴越右统军使。943年条下记章德安与李文庆被贬后，史书称他与阚璠更加专横。生卒年尚未核。", "biography": null, "status": "draft", "id": "4f56160f-2b15-5a0c-9fa8-9523947bb1df"}, {"name": "何承训", "aliases": ["何承訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越内牙指挥使。947年与钱弘倧商议驱逐胡进思，后来担忧事泄，反向胡进思告知谋议。与后汉皇子刘承训、霍彦威之子霍承训分别建档。生卒年尚未录入。", "biography": null, "status": "draft", "id": "ed6fa1b8-f022-57b2-9729-421b42a24e17"}, {"name": "水丘昭券", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临安人，吴越内都监使。946年福州求救时，他主张出兵。钱弘佐让他掌管用兵，他因忌惮程昭悦而让出此事。原文未载生卒年。", "biography": null, "status": "draft", "id": "f1cf3b01-3f76-5d76-92a7-87fd41eb433c"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "元德昭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "危仔倡之子。946年吴越出兵救福州时，钱弘佐把军事谋划交给他。其姓名与父亲异姓按史书记载保留，不据此猜测改姓原因或收养关系；生卒年未载。", "biography": null, "status": "draft", "id": "3f40b6ff-27d0-5eae-a8f2-983b144f4081"}, {"name": "鹿光铉", "aliases": ["鹿光鉉", "鹿光弦"], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "钱弘倧的舅父，任进侍。947年年末胡进思发动废立后将其杀害。《资治通鉴》同段姓名写作光铉、光弦，沿同一人保留异字。出生年未载。", "biography": null, "status": "draft", "id": "d65fa049-1d3c-579a-b071-de224b0e5df8"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
